// Bilinear sample of a grid at fractional post (x, y), clamped to the grid. A grid one post wide or
// high is sampled along its other axis only.
export function bilinear(grid, width, height, x, y) {
  const x0 = Math.max(0, Math.min(Math.floor(x), width - 2));
  const y0 = Math.max(0, Math.min(Math.floor(y), height - 2));
  const x1 = Math.min(x0 + 1, width - 1);
  const y1 = Math.min(y0 + 1, height - 1);
  const fx = x1 === x0 ? 0 : Math.min(Math.max(x - x0, 0), 1);
  const fy = y1 === y0 ? 0 : Math.min(Math.max(y - y0, 0), 1);
  const top = grid[y0 * width + x0] * (1 - fx) + grid[y0 * width + x1] * fx;
  const bottom = grid[y1 * width + x0] * (1 - fx) + grid[y1 * width + x1] * fx;
  return top * (1 - fy) + bottom * fy;
}

