import { test } from 'node:test';
import assert from 'node:assert/strict';
import { bilinear } from '../src/bilinear.js';

test('a 2 x 2 grid interpolates in both axes', () => {
  assert.equal(bilinear([0, 2, 4, 6], 2, 2, 0.5, 0.5), 3);
  assert.equal(bilinear([0, 2, 4, 6], 2, 2, 5, 5), 6);
});

test('a one-post grid returns its post', () => {
  assert.equal(bilinear([7], 1, 1, 0.3, 0.8), 7);
});

test('a single row and a single column interpolate along their length', () => {
  assert.equal(bilinear([0, 10, 20], 3, 1, 1.5, 0), 15);
  assert.equal(bilinear([0, 10, 20], 1, 3, 0, 0.5), 5);
});
